{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "Ensure that VPC Flow Logs is enabled for every subnet in a VPC Network",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "VPC Flow Logs are not enabled for this subnet. Enabling flow logs helps with network monitoring, troubleshooting, and security analysis by capturing information about the IP traffic going to and from network interfaces."
    }
  ],
  "patched_code": "resource \"google_compute_subnetwork\" \"data_subnet\" {\n  name                     = \"hipaa-compliant-patient-portal-subnet-data\"\n  ip_cidr_range            = \"10.0.3.0/24\"\n  region                   = var.region\n  network                  = google_compute_network.hipaa_vpc.id\n  private_ip_google_access = true\n\n  log_config {\n    aggregation_interval = \"INTERVAL_5_SEC\"\n    flow_sampling        = 0.5\n    metadata             = \"INCLUDE_ALL_METADATA\"\n  }\n}",
  "fix_summary": "Enabled VPC Flow Logs for the subnet by adding a `log_config` block with appropriate settings for aggregation interval, flow sampling, and metadata."
}
